"""Every event name Yoke emits, with the metadata the registry serves.

This table is the only source of ``event_registry`` membership. Each boot
projects it into the table exactly (:mod:`event_registry_converge`): a row
here is inserted or updated, and a registry row whose name is absent here is
deleted. Add a row in name order when code, a skill or the web UI starts
emitting a name; delete the row in the change that removes its last producer.
An emitted name with no row here is reported by the registry audit and the
``HC-event-registry-coverage`` doctor check as rogue.
"""

from __future__ import annotations

from types import MappingProxyType
from typing import Mapping, NamedTuple


class EventSpec(NamedTuple):
    name: str
    kind: str
    event_type: str
    owner_service: str
    severity: str
    description: str


