def _index(specs: tuple[EventSpec, ...]) -> Mapping[str, EventSpec]:
    catalog: dict[str, EventSpec] = {}
    for spec in specs:
        if spec.name in catalog:
            raise ValueError(
                f"event catalog lists {spec.name!r} twice; keep one row per name"
            )
        catalog[spec.name] = spec
    return MappingProxyType(catalog)


EVENT_CATALOG: Mapping[str, EventSpec] = _index(_SPECS)


__all__ = ["EVENT_CATALOG", "EventSpec"]
